import json,sys; sys.path.insert(0,d)
from lib import shapes
def transform2(g):
    h,w=len(g),len(g[0]); boxes=sorted(shapes(g), key=lambda b:b[1])
    out=[[0]*w for _ in range(h)]; top=0
    for k,(r0,c0,r1,c1,col) in enumerate(boxes):
        bh,bw=r1-r0+1,c1-c0+1
        for a in range(bh):
            for b in range(bw): out[top+a][k+b]=col
        top+=bh-1
    return out
